                        <div className="text-xs font-mono opacity-50 mt-0.5">{p.romanization}</div>
                        <div className="text-sm opacity-70 mt-1">{p.meaning}</div>
                      </div>
                    ))}
                  </div>
                </section>
              </div>
            );
          })

