                    ))}
                  </div>
                </section>

                {/* Hours clock grid */}
                <section className="space-y-4">
                  <h2 className="text-xl font-bold">시 Hours <span className="text-sm font-normal opacity-50 ml-2">(Native Korean numbers)</span></h2>
